import type { ContentPack } from '../types';
import { glesson as G, lesson, M, Nq, TF } from '../lib';
import { mendel } from '../gensSci';

const P: ContentPack = {
  '4E-BG-1': lesson(['Una hipótesis es una respuesta provisional que se puede poner a prueba. El diseño experimental define la variable independiente (la que cambio), la dependiente (la que mido), las controladas (iguales en todo) y un grupo de control. Repetir el experimento da fiabilidad.|Una hipòtesi és una resposta provisional que es pot posar a prova. El disseny experimental definix la variable independent (la que canvie), la dependent (la que mesure), les controlades (iguals en tot) i un grup de control. Repetir l’experiment dona fiabilitat.|A hypothesis is a provisional answer that can be tested. An experimental design sets the independent variable (what I change), the dependent variable (what I measure), the control variables (kept the same) and a control group. Repeating the experiment makes it reliable.'],
    '¿Afecta la sal a la germinación de las semillas de rábano?|Afecta la sal a la germinació de les llavors de rave?|Does salt affect radish seed germination?', ['Independiente: concentración de sal. Dependiente: % de semillas germinadas.|Independent: concentració de sal. Dependent: % de llavors germinades.|Independent: salt concentration. Dependent: % of seeds that germinate.', 'Control: agua sin sal; misma luz, temperatura y número de semillas.|Control: aigua sense sal; mateixa llum, temperatura i nombre de llavors.|Control: water with no salt; same light, temperature and number of seeds.'], [
      M('En el experimento de la sal, ¿cuál es una variable controlada?|En l’experiment de la sal, quina és una variable controlada?|In the salt experiment, which is a control variable?', 'la temperatura|la temperatura|the temperature', ['la concentración de sal|la concentració de sal|the salt concentration', 'el número de semillas germinadas|el nombre de llavors germinades|the number of seeds germinating'], 'Se mantiene igual en todas las placas.|Es manté igual en totes les plaques.|Kept the same in every dish.'),
      M('Una hipótesis contrastable es…|Una hipòtesi contrastable és…|A testable hypothesis is…', '«A más sal, menos semillas germinan»|«A més sal, menys llavors germinen»|"More salt means fewer seeds germinate"', ['«Las semillas son felices»|«Les llavors són feliços»|"Seeds are happy"', '«La sal es mala»|«La sal és roïna»|"Salt is bad"'], 'Relaciona variables medibles.|Relaciona variables mesurables.|It links measurable variables.'),
      TF('Si solo usas una semilla por grupo, los resultados son poco fiables.|Si només uses una llavor per grup, els resultats són poc fiables.|Using only one seed per group gives unreliable results.', true, 'Muestras grandes y repeticiones.|Mostres grans i repeticions.|Large samples and repeats.'),
      M('El grupo de control sirve para…|El grup de control servix per a…|The control group is used to…', 'comparar y ver el efecto real de la variable|comparar i veure l’efecte real de la variable|compare and see the real effect of the variable', ['tener más datos sin motivo|tindre més dades sense motiu|get more data for no reason', 'evitar medir|evitar mesurar|avoid measuring'], 'Sin él no hay comparación.|Sense ell no hi ha comparació.|Without it there is no comparison.'),
      M('Si los resultados contradicen la hipótesis…|Si els resultats contradiuen la hipòtesi…|If the results contradict the hypothesis…', 'se rechaza o se reformula|es rebutja o es reformula|it is rejected or rewritten', ['se cambian los datos|es canvien les dades|the data is changed', 'se ignoran|s’ignoren|they are ignored'], 'Honestidad científica.|Honestedat científica.|Scientific honesty.'),
      TF('Un experimento doble ciego evita que las expectativas influyan en el resultado.|Un experiment doble cec evita que les expectatives influïsquen en el resultat.|A double-blind experiment stops expectations influencing the result.', true, 'Ni participantes ni investigadores saben quién recibe el tratamiento.|Ni participants ni investigadors saben qui rep el tractament.|Neither participants nor researchers know who gets the treatment.'),
    ]),
  '4E-BG-2': lesson(['Teoría celular: todos los seres vivos están formados por células, la célula es la unidad funcional y toda célula procede de otra. Tipos: procariota (sin núcleo, como las bacterias) y eucariota (con núcleo y orgánulos: mitocondrias, retículo, aparato de Golgi, ribosomas; en vegetales, cloroplastos y pared).|Teoria cel·lular: tots els éssers vius estan formats per cèl·lules, la cèl·lula és la unitat funcional i tota cèl·lula procedix d’una altra. Tipus: procariota (sense nucli, com els bacteris) i eucariota (amb nucli i orgànuls: mitocondris, reticle, aparell de Golgi, ribosomes; en vegetals, cloroplasts i paret).|Cell theory: all living things are made of cells, the cell is the basic functional unit and every cell comes from another cell. Types: prokaryotic (no nucleus, such as bacteria) and eukaryotic (nucleus and organelles: mitochondria, ER, Golgi apparatus, ribosomes; in plants, chloroplasts and a wall).'],
    '¿Qué orgánulo tienen todas las células, incluso las bacterias?|Quin orgànul tenen totes les cèl·lules, fins i tot els bacteris?|Which structure do all cells have, even bacteria?', ['Fabrican proteínas.|Fabriquen proteïnes.|They make proteins.', 'Los ribosomas.|Els ribosomes.|Ribosomes.'], [
      M('¿Qué orgánulo realiza la respiración celular?|Quin orgànul realitza la respiració cel·lular?|Which organelle carries out cellular respiration?', 'la mitocondria|el mitocondri|the mitochondrion', ['el aparato de Golgi|l’aparell de Golgi|the Golgi apparatus', 'el ribosoma|el ribosoma|the ribosome'], 'Obtiene energía de la glucosa.|Obté energia de la glucosa.|It releases energy from glucose.'),
      M('«Toda célula procede de otra célula» lo afirmó…|«Tota cèl·lula procedix d’una altra cèl·lula» ho va afirmar…|"Every cell comes from another cell" was stated by…', 'Virchow|Virchow|Virchow', ['Newton|Newton|Newton', 'Wegener|Wegener|Wegener'], 'Omnis cellula e cellula.|Omnis cellula e cellula.|Omnis cellula e cellula.'),
      M('El aparato de Golgi se encarga de…|L’aparell de Golgi s’encarrega de…|The Golgi apparatus…', 'empaquetar y enviar sustancias|empaquetar i enviar substàncies|packages and ships substances', ['hacer la fotosíntesis|fer la fotosíntesi|carries out photosynthesis', 'guardar el ADN|guardar l’ADN|stores DNA'], 'Como una oficina de correos.|Com una oficina de correus.|Like a post office.'),
      TF('Las células vegetales tienen mitocondrias además de cloroplastos.|Les cèl·lules vegetals tenen mitocondris a més de cloroplasts.|Plant cells have mitochondria as well as chloroplasts.', true, 'También respiran.|També respiren.|They respire too.'),
      M('Una diferencia de las procariotas es que…|Una diferència de les procariotes és que…|One feature of prokaryotes is that…', 'su ADN está libre en el citoplasma|el seu ADN està lliure en el citoplasma|their DNA is loose in the cytoplasm', ['tienen muchos núcleos|tenen molts nuclis|they have many nuclei', 'son siempre pluricelulares|són sempre pluricel·lulars|they are always many-celled'], 'No hay envoltura nuclear.|No hi ha embolcall nuclear.|No nuclear membrane.'),
      M('El retículo endoplasmático rugoso tiene ribosomas y fabrica…|El reticle endoplasmàtic rugós té ribosomes i fabrica…|The rough ER has ribosomes and makes…', 'proteínas|proteïnes|proteins', ['almidón|midó|starch', 'clorofila|clorofil·la|chlorophyll'], 'Rugoso por los ribosomas.|Rugós pels ribosomes.|Rough because of the ribosomes.'),
    ]),
  '4E-BG-3': lesson(['Ciclo celular: interfase (la célula crece y copia su ADN) y división. Mitosis: una célula da dos células hijas idénticas (crecimiento y reparación). Meiosis: una célula da cuatro células con la mitad de cromosomas (gametos) y con variación genética.|Cicle cel·lular: interfase (la cèl·lula creix i copia el seu ADN) i divisió. Mitosi: una cèl·lula dona dues cèl·lules filles idèntiques (creixement i reparació). Meiosi: una cèl·lula dona quatre cèl·lules amb la meitat de cromosomes (gàmetes) i amb variació genètica.|Cell cycle: interphase (the cell grows and copies its DNA) and division. Mitosis: one cell makes two identical daughter cells (growth and repair). Meiosis: one cell makes four cells with half the chromosomes (gametes) and genetic variation.'],
    'Una célula humana tiene 46 cromosomas. ¿Y un espermatozoide?|Una cèl·lula humana té 46 cromosomes. I un espermatozou?|A human cell has 46 chromosomes. How many does a sperm cell have?', ['Los gametos se forman por meiosis.|Els gàmetes es formen per meiosi.|Gametes are made by meiosis.', 'La mitad: 23.|La meitat: 23.|Half: 23.'], [
      Nq('¿Cuántas células hijas produce la mitosis?|Quantes cèl·lules filles produïx la mitosi?|How many daughter cells does mitosis produce?', 2, [4, 1, 8], 'Idénticas a la madre.|Idèntiques a la mare.|Identical to the parent.'),
      Nq('¿Cuántas células produce la meiosis a partir de una?|Quantes cèl·lules produïx la meiosi a partir d’una?|How many cells does meiosis make from one?', 4, [2, 1, 46], 'Con la mitad de cromosomas.|Amb la meitat de cromosomes.|With half the chromosomes.'),
      M('Al curarse una herida, la piel se regenera por…|En curar-se una ferida, la pell es regenera per…|When a wound heals, skin regrows by…', 'mitosis|mitosi|mitosis', ['meiosis|meiosi|meiosis', 'fecundación|fecundació|fertilisation'], 'Células idénticas.|Cèl·lules idèntiques.|Identical cells.'),
      TF('La meiosis produce variabilidad genética.|La meiosi produïx variabilitat genètica.|Meiosis produces genetic variation.', true, 'Por eso los hermanos no son idénticos.|Per això els germans no són idèntics.|That is why siblings differ.'),
      M('Durante la interfase, la célula…|Durant la interfase, la cèl·lula…|During interphase, the cell…', 'duplica su ADN|duplica el seu ADN|copies its DNA', ['se divide|es dividix|divides', 'muere|mor|dies'], 'Se prepara para dividirse.|Es prepara per a dividir-se.|It prepares to divide.'),
      M('El cáncer se debe a…|El càncer es deu a…|Cancer is caused by…', 'divisiones celulares sin control|divisions cel·lulars sense control|cells dividing out of control', ['falta de meiosis|falta de meiosi|a lack of meiosis', 'exceso de vitaminas|excés de vitamines|too many vitamins'], 'Mutaciones en genes que controlan el ciclo.|Mutacions en gens que controlen el cicle.|Mutations in genes that control the cycle.'),
    ]),
  '4E-BG-4': lesson(['El ADN es la molécula que guarda la información genética: una doble hélice de nucleótidos con cuatro bases (A, T, C, G); A se une con T y C con G. Un gen es un fragmento de ADN con la información para una proteína. El ARN (con U en lugar de T) copia esa información y la lleva a los ribosomas.|L’ADN és la molècula que guarda la informació genètica: una doble hèlix de nucleòtids amb quatre bases (A, T, C, G); A s’unix amb T i C amb G. Un gen és un fragment d’ADN amb la informació per a una proteïna. L’ARN (amb U en lloc de T) copia eixa informació i la porta als ribosomes.|DNA is the molecule that stores genetic information: a double helix of nucleotides with four bases (A, T, C, G); A pairs with T and C with G. A gene is a stretch of DNA coding for a protein. RNA (with U instead of T) copies that information and carries it to the ribosomes.'],
    '¿Qué cadena complementa a ATTGC?|Quina cadena complementa ATTGC?|What strand pairs with ATTGC?', ['A–T, T–A, C–G, G–C.|A–T, T–A, C–G, G–C.|A–T, T–A, C–G, G–C.', 'TAACG.|TAACG.|TAACG.'], [
      M('¿Qué base se une con la citosina (C) en el ADN?|Quina base s’unix amb la citosina (C) en l’ADN?|Which base pairs with cytosine (C) in DNA?', 'guanina (G)|guanina (G)|guanine (G)', ['timina (T)|timina (T)|thymine (T)', 'adenina (A)|adenina (A)|adenine (A)'], 'C–G.|C–G.|C–G.'),
      M('Complementaria del ADN GGATC:|Complementària de l’ADN GGATC:|Complementary DNA strand to GGATC:', 'CCTAG|CCTAG|CCTAG', ['GGATC|GGATC|GGATC', 'CCUAG|CCUAG|CCUAG'], 'En el ADN no hay U.|En l’ADN no hi ha U.|DNA has no U.'),
      M('El ARN tiene uracilo (U) en lugar de…|L’ARN té uracil (U) en lloc de…|RNA has uracil (U) instead of…', 'timina (T)|timina (T)|thymine (T)', ['adenina (A)|adenina (A)|adenine (A)', 'guanina (G)|guanina (G)|guanine (G)'], 'U se empareja con A.|U s’aparella amb A.|U pairs with A.'),
      TF('El ADN de una persona es igual en casi todas sus células.|L’ADN d’una persona és igual en quasi totes les seues cèl·lules.|A person’s DNA is the same in almost all their cells.', true, 'Por eso sirve para identificar.|Per això servix per a identificar.|That is why it can identify people.'),
      M('La estructura de doble hélice la describieron…|L’estructura de doble hèlix la van descriure…|The double helix was described by…', 'Watson y Crick, con datos de Rosalind Franklin|Watson i Crick, amb dades de Rosalind Franklin|Watson and Crick, using Rosalind Franklin’s data', ['Darwin y Wallace|Darwin i Wallace|Darwin and Wallace', 'Newton y Hooke|Newton i Hooke|Newton and Hooke'], 'En 1953.|El 1953.|In 1953.'),
      M('Un gen contiene la información para fabricar…|Un gen conté la informació per a fabricar…|A gene holds the information to make…', 'una proteína|una proteïna|a protein', ['un hueso entero|un os sencer|a whole bone', 'una célula|una cèl·lula|a cell'], 'Las proteínas hacen el trabajo celular.|Les proteïnes fan el treball cel·lular.|Proteins do the cell’s work.'),
    ]),
  '4E-BG-5': lesson(['Una mutación es un cambio en el ADN. Puede ser génica (cambia una o pocas bases), cromosómica (cambia un trozo de cromosoma) o genómica (cambia el número de cromosomas, como el síndrome de Down: trisomía 21). Causas: errores al copiar el ADN, radiaciones, ciertas sustancias. Son la fuente de variación que permite la evolución.|Una mutació és un canvi en l’ADN. Pot ser gènica (canvia una o poques bases), cromosòmica (canvia un tros de cromosoma) o genòmica (canvia el nombre de cromosomes, com la síndrome de Down: trisomia 21). Causes: errors en copiar l’ADN, radiacions, certes substàncies. Són la font de variació que permet l’evolució.|A mutation is a change in DNA. It can be a gene mutation (one or a few bases change), chromosomal (part of a chromosome changes) or genomic (the number of chromosomes changes, such as Down syndrome: trisomy 21). Causes: copying errors, radiation, certain substances. They are the source of variation that makes evolution possible.'],
    '¿Todas las mutaciones son perjudiciales?|Totes les mutacions són perjudicials?|Are all mutations harmful?', ['Muchas no tienen efecto.|Moltes no tenen efecte.|Many have no effect.', 'Algunas son beneficiosas y permiten la evolución.|Algunes són beneficioses i permeten l’evolució.|Some are beneficial and drive evolution.'], [
      M('El síndrome de Down se debe a…|La síndrome de Down es deu a…|Down syndrome is due to…', 'una copia extra del cromosoma 21|una còpia extra del cromosoma 21|an extra copy of chromosome 21', ['falta de vitaminas|falta de vitamines|a lack of vitamins', 'una infección|una infecció|an infection'], 'Mutación genómica (trisomía).|Mutació genòmica (trisomia).|A genomic mutation (trisomy).'),
      M('Un agente que puede causar mutaciones es…|Un agent que pot causar mutacions és…|Something that can cause mutations is…', 'la radiación ultravioleta|la radiació ultraviolada|ultraviolet radiation', ['el agua|l’aigua|water', 'el sueño|la son|sleep'], 'Por eso hay que protegerse del sol.|Per això cal protegir-se del sol.|So protect yourself from the sun.'),
      TF('Las mutaciones en los gametos pueden heredarse.|Les mutacions en els gàmetes es poden heretar.|Mutations in gametes can be inherited.', true, 'Pasan a la descendencia.|Passen a la descendència.|They pass to offspring.'),
      M('Una mutación génica afecta a…|Una mutació gènica afecta…|A gene mutation affects…', 'una o pocas bases del ADN|una o poques bases de l’ADN|one or a few DNA bases', ['el número de cromosomas|el nombre de cromosomes|the number of chromosomes', 'todo el cuerpo a la vez|tot el cos alhora|the whole body at once'], 'Como la anemia falciforme.|Com l’anèmia falciforme.|Such as sickle-cell anaemia.'),
      TF('Sin mutaciones no habría variación genética para la evolución.|Sense mutacions no hi hauria variació genètica per a l’evolució.|Without mutations there would be no genetic variation for evolution.', true, 'Son la materia prima.|Són la matèria primera.|They are the raw material.'),
      M('La resistencia de bacterias a antibióticos aparece por…|La resistència de bacteris a antibiòtics apareix per…|Antibiotic resistance in bacteria arises from…', 'mutaciones y selección|mutacions i selecció|mutation and selection', ['falta de agua|falta d’aigua|lack of water', 'el frío|el fred|cold'], 'Sobreviven las resistentes.|Sobreviuen els resistents.|The resistant ones survive.'),
    ]),
  '4E-BG-6': G(['Mendel estudió la herencia con guisantes. Cada carácter depende de dos alelos (uno de cada progenitor). Dominante (A) se manifiesta siempre; recesivo (a) solo si hay dos (aa). Homocigoto: AA o aa; heterocigoto: Aa. El cuadro de Punnett predice las proporciones.|Mendel va estudiar l’herència amb pésols. Cada caràcter depén de dos al·lels (un de cada progenitor). Dominant (A) es manifesta sempre; recessiu (a) només si n’hi ha dos (aa). Homozigot: AA o aa; heterozigot: Aa. El quadre de Punnett prediu les proporcions.|Mendel studied heredity using peas. Each trait depends on two alleles (one from each parent). A dominant allele (A) always shows; a recessive one (a) shows only in aa. Homozygous: AA or aa; heterozygous: Aa. A Punnett square predicts the ratios.'],
    'Aa × Aa. ¿Proporción de descendientes aa?|Aa × Aa. Proporció de descendents aa?|Aa × Aa. Proportion of aa offspring?', ['Combinaciones: AA, Aa, aA, aa.|Combinacions: AA, Aa, aA, aa.|Combinations: AA, Aa, aA, aa.', '1 de cada 4 (25 %).|1 de cada 4 (25 %).|1 in 4 (25%).'], mendel(), [
      M('Un individuo Aa es…|Un individu Aa és…|An Aa individual is…', 'heterocigoto|heterozigot|heterozygous', ['homocigoto dominante|homozigot dominant|homozygous dominant', 'homocigoto recesivo|homozigot recessiu|homozygous recessive'], 'Dos alelos distintos.|Dos al·lels diferents.|Two different alleles.'),
    ]),
  '4E-BG-7': lesson(['Herencia humana: algunos caracteres siguen las leyes de Mendel (grupo sanguíneo, lóbulo de la oreja). El sexo lo determinan los cromosomas X e Y (XX, XY). Algunas enfermedades están ligadas al cromosoma X, como el daltonismo o la hemofilia, y son más frecuentes en hombres.|Herència humana: alguns caràcters seguixen les lleis de Mendel (grup sanguini, lòbul de l’orella). El sexe el determinen els cromosomes X i Y (XX, XY). Algunes malalties estan lligades al cromosoma X, com el daltonisme o l’hemofília, i són més freqüents en homes.|Human heredity: some traits follow Mendel’s laws (blood group, ear lobes). Sex is determined by the X and Y chromosomes (XX, XY). Some conditions are X-linked, such as colour blindness and haemophilia, and are more common in males.'],
    '¿Por qué el daltonismo es más frecuente en hombres?|Per què el daltonisme és més freqüent en homes?|Why is colour blindness more common in males?', ['El gen está en el cromosoma X.|El gen està en el cromosoma X.|The gene is on the X chromosome.', 'Los hombres tienen un solo X: si lo llevan, lo manifiestan.|Els homes tenen un sol X: si el porten, el manifesten.|Males have one X: if they carry it, it shows.'], [
      M('Los grupos sanguíneos A y B son…|Els grups sanguinis A i B són…|Blood groups A and B are…', 'codominantes|codominants|codominant', ['recesivos|recessius|recessive', 'ligados al Y|lligats al Y|Y-linked'], 'Por eso existe el grupo AB.|Per això existix el grup AB.|That is why group AB exists.'),
      Nq('¿Cuántos cromosomas tiene una célula humana no sexual?|Quants cromosomes té una cèl·lula humana no sexual?|How many chromosomes does a human body cell have?', 46, [23, 48, 92], '23 parejas.|23 parelles.|23 pairs.'),
      M('Una mujer tiene los cromosomas sexuales…|Una dona té els cromosomes sexuals…|A female has the sex chromosomes…', 'XX|XX|XX', ['XY|XY|XY', 'YY|YY|YY'], 'El hombre, XY.|L’home, XY.|A male has XY.'),
      TF('El grupo sanguíneo O es recesivo frente a A y B.|El grup sanguini O és recessiu respecte d’A i B.|Blood group O is recessive to A and B.', true, 'Una persona O es OO.|Una persona O és OO.|A group O person is OO.'),
      M('La hemofilia afecta a…|L’hemofília afecta…|Haemophilia affects…', 'la coagulación de la sangre|la coagulació de la sang|blood clotting', ['la vista|la vista|eyesight', 'el oído|l’oïda|hearing'], 'Ligada al cromosoma X.|Lligada al cromosoma X.|X-linked.'),
      M('Un cariotipo es…|Un cariotip és…|A karyotype is…', 'la imagen ordenada de los cromosomas de una célula|la imatge ordenada dels cromosomes d’una cèl·lula|an ordered picture of a cell’s chromosomes', ['un tipo de sangre|un tipus de sang|a blood type', 'un órgano|un òrgan|an organ'], 'Sirve para detectar alteraciones.|Servix per a detectar alteracions.|It reveals abnormalities.'),
    ]),
  '4E-BG-8': lesson(['La Tierra tiene unos 4 600 millones de años y la vida apareció hace más de 3 500. Hipótesis: síntesis de moléculas orgánicas en la Tierra primitiva (experimento de Miller y Urey), fuentes hidrotermales, llegada de moléculas en meteoritos. Los primeros seres eran procariotas; después surgieron eucariotas y pluricelulares.|La Terra té uns 4 600 milions d’anys i la vida va aparéixer fa més de 3 500. Hipòtesis: síntesi de molècules orgàniques en la Terra primitiva (experiment de Miller i Urey), fonts hidrotermals, arribada de molècules en meteorits. Els primers éssers eren procariotes; després van sorgir eucariotes i pluricel·lulars.|The Earth is about 4.6 billion years old and life appeared over 3.5 billion years ago. Hypotheses: organic molecules formed on the early Earth (Miller–Urey experiment), hydrothermal vents, molecules arriving on meteorites. The first organisms were prokaryotes; eukaryotes and many-celled life came later.'],
    '¿Qué demostró el experimento de Miller y Urey (1953)?|Què va demostrar l’experiment de Miller i Urey (1953)?|What did the Miller–Urey experiment (1953) show?', ['Simularon la atmósfera primitiva con descargas eléctricas.|Van simular l’atmosfera primitiva amb descàrregues elèctriques.|They simulated the early atmosphere with electric sparks.', 'Se formaron aminoácidos a partir de moléculas sencillas.|Es van formar aminoàcids a partir de molècules senzilles.|Amino acids formed from simple molecules.'], [
      M('Los primeros seres vivos fueron…|Els primers éssers vius van ser…|The first living things were…', 'procariotas unicelulares|procariotes unicel·lulars|single-celled prokaryotes', ['dinosaurios|dinosaures|dinosaurs', 'plantas con flores|plantes amb flors|flowering plants'], 'Parecidos a bacterias.|Semblants a bacteris.|Similar to bacteria.'),
      M('Los estromatolitos son…|Els estromatòlits són…|Stromatolites are…', 'rocas formadas por bacterias muy antiguas|roques formades per bacteris molt antics|rocks built by ancient bacteria', ['meteoritos|meteorits|meteorites', 'huesos fósiles|ossos fòssils|fossil bones'], 'Algunos tienen más de 3 000 millones de años.|Alguns tenen més de 3 000 milions d’anys.|Some are over 3 billion years old.'),
      TF('El oxígeno de la atmósfera lo produjeron organismos fotosintéticos.|L’oxigen de l’atmosfera el van produir organismes fotosintètics.|Atmospheric oxygen was produced by photosynthetic organisms.', true, 'Cianobacterias.|Cianobacteris.|Cyanobacteria.'),
      M('La teoría endosimbiótica explica el origen de…|La teoria endosimbiòtica explica l’origen de…|Endosymbiotic theory explains the origin of…', 'mitocondrias y cloroplastos|mitocondris i cloroplasts|mitochondria and chloroplasts', ['los huesos|els ossos|bones', 'los volcanes|els volcans|volcanoes'], 'Eran bacterias que vivían dentro de otra célula.|Eren bacteris que vivien dins d’una altra cèl·lula.|They were bacteria living inside another cell.'),
      TF('La generación espontánea (vida de la materia inerte, como gusanos de la carne) fue refutada por Pasteur.|La generació espontània (vida de la matèria inert, com cucs de la carn) la va refutar Pasteur.|Spontaneous generation (life from non-living matter, like maggots from meat) was disproved by Pasteur.', true, 'Matraces de cuello de cisne.|Matrassos de coll de cigne.|Swan-neck flasks.'),
      M('Una propuesta sobre el origen de la vida sitúa su inicio en…|Una proposta sobre l’origen de la vida situa el seu inici en…|One idea places the start of life at…', 'fuentes hidrotermales del fondo oceánico|fonts hidrotermals del fons oceànic|hydrothermal vents on the ocean floor', ['la cima del Everest|el cim de l’Everest|the top of Everest', 'el interior del Sol|l’interior del Sol|inside the Sun'], 'Calor y minerales.|Calor i minerals.|Heat and minerals.'),
    ]),
  '4E-BG-9': lesson(['Pruebas de la evolución: fósiles (formas intermedias como Archaeopteryx), anatomía comparada (órganos homólogos: brazo humano, ala de murciélago, aleta de ballena), embriología, distribución geográfica (pinzones de las Galápagos) y biología molecular (parecidos en el ADN).|Proves de l’evolució: fòssils (formes intermèdies com Archaeopteryx), anatomia comparada (òrgans homòlegs: braç humà, ala de rata penada, aleta de balena), embriologia, distribució geogràfica (pinsans de les Galápagos) i biologia molecular (semblances en l’ADN).|Evidence for evolution: fossils (intermediate forms such as Archaeopteryx), comparative anatomy (homologous organs: human arm, bat wing, whale flipper), embryology, geographical distribution (Galápagos finches) and molecular biology (DNA similarities).'],
    '¿Por qué el brazo humano y el ala del murciélago tienen los mismos huesos?|Per què el braç humà i l’ala de la rata penada tenen els mateixos ossos?|Why do a human arm and a bat wing have the same bones?', ['Son órganos homólogos.|Són òrgans homòlegs.|They are homologous organs.', 'Proceden de un antepasado común.|Procedixen d’un avantpassat comú.|They come from a common ancestor.'], [
      M('Archaeopteryx es una prueba de la relación entre…|Archaeopteryx és una prova de la relació entre…|Archaeopteryx shows the link between…', 'dinosaurios y aves|dinosaures i ocells|dinosaurs and birds', ['peces y mamíferos|peixos i mamífers|fish and mammals', 'plantas y hongos|plantes i fongs|plants and fungi'], 'Tenía plumas y dientes.|Tenia plomes i dents.|It had feathers and teeth.'),
      M('El ala de un insecto y la de un ave son órganos…|L’ala d’un insecte i la d’un ocell són òrgans…|An insect wing and a bird wing are…', 'análogos|anàlegs|analogous organs', ['homólogos|homòlegs|homologous organs', 'vestigiales|vestigials|vestigial organs'], 'Misma función, distinto origen.|Mateixa funció, origen diferent.|Same job, different origin.'),
      TF('Humanos y chimpancés comparten un porcentaje muy alto de su ADN.|Humans i ximpanzés compartixen un percentatge molt alt del seu ADN.|Humans and chimpanzees share a very high percentage of their DNA.', true, 'En torno al 98 %.|Al voltant del 98 %.|About 98%.'),
      M('Los pinzones de las Galápagos tienen picos distintos según…|Els pinsans de les Galápagos tenen becs diferents segons…|Galápagos finches have different beaks depending on…', 'el alimento de cada isla|l’aliment de cada illa|the food on each island', ['su color|el seu color|their colour', 'la época del año|l’època de l’any|the season'], 'Adaptación al medio.|Adaptació al medi.|Adaptation to the environment.'),
      M('Un órgano vestigial en humanos es…|Un òrgan vestigial en humans és…|A vestigial organ in humans is…', 'el coxis|el còccix|the coccyx', ['el corazón|el cor|the heart', 'el hígado|el fetge|the liver'], 'Resto de una cola ancestral.|Resta d’una cua ancestral.|A remnant of an ancestral tail.'),
      TF('Darwin observó fósiles y especies en su viaje en el Beagle.|Darwin va observar fòssils i espècies en el seu viatge en el Beagle.|Darwin observed fossils and species on his Beagle voyage.', true, 'Viaje de 1831 a 1836.|Viatge de 1831 a 1836.|Voyage from 1831 to 1836.'),
    ]),
  '4E-BG-10': lesson(['Selección natural (Darwin y Wallace): en una población hay variación; nacen más individuos de los que pueden sobrevivir; los mejor adaptados sobreviven y se reproducen más, y transmiten sus caracteres. Con el tiempo, las poblaciones cambian. La teoría actual (neodarwinismo) añade la genética: mutaciones y recombinación.|Selecció natural (Darwin i Wallace): en una població hi ha variació; naixen més individus dels que poden sobreviure; els millor adaptats sobreviuen i es reproduïxen més, i transmeten els seus caràcters. Amb el temps, les poblacions canvien. La teoria actual (neodarwinisme) afig la genètica: mutacions i recombinació.|Natural selection (Darwin and Wallace): populations vary; more are born than can survive; the best adapted survive and reproduce more, passing on their traits. Over time, populations change. The modern theory (neo-Darwinism) adds genetics: mutation and recombination.'],
    'Polillas claras y oscuras en Inglaterra. Con la contaminación, los troncos se oscurecieron. ¿Qué pasó?|Arnes clares i fosques a Anglaterra. Amb la contaminació, els troncs es van enfosquir. Què va passar?|Light and dark moths in England. Pollution darkened tree trunks. What happened?', ['Las claras se veían más y los pájaros las comían.|Les clares es veien més i els ocells se les menjaven.|The light ones were easier to see and birds ate them.', 'Aumentaron las oscuras: selección natural.|Van augmentar les fosques: selecció natural.|Dark moths increased: natural selection.'], [
      M('Según Lamarck, la jirafa tiene el cuello largo porque…|Segons Lamarck, la girafa té el coll llarg perquè…|According to Lamarck, giraffes have long necks because…', 'lo estiraba para comer y lo heredaban sus hijas|l’estirava per a menjar i l’heretaven les filles|they stretched them to eat and passed that on', ['las de cuello largo sobrevivían más|les de coll llarg sobrevivien més|long-necked ones survived better', 'así lo eligieron|així ho van triar|they chose it'], 'Herencia de caracteres adquiridos (incorrecta).|Herència de caràcters adquirits (incorrecta).|Inheritance of acquired traits (wrong).'),
      M('Según Darwin, la jirafa tiene el cuello largo porque…|Segons Darwin, la girafa té el coll llarg perquè…|According to Darwin, giraffes have long necks because…', 'las de cuello más largo sobrevivían y se reproducían más|les de coll més llarg sobrevivien i es reproduïen més|those with longer necks survived and bred more', ['lo estiraban mucho|l’estiraven molt|they stretched them a lot', 'comían más hojas desde pequeñas|menjaven més fulles des de xicotetes|they ate more leaves when young'], 'Selección natural.|Selecció natural.|Natural selection.'),
      TF('La selección natural actúa sobre individuos, pero son las poblaciones las que evolucionan.|La selecció natural actua sobre individus, però són les poblacions les que evolucionen.|Natural selection acts on individuals, but populations evolve.', true, 'Cambian las frecuencias de los genes.|Canvien les freqüències dels gens.|Gene frequencies change.'),
      M('La resistencia de los insectos a un insecticida es un ejemplo de…|La resistència dels insectes a un insecticida és un exemple de…|Insects becoming resistant to insecticide is an example of…', 'selección natural|selecció natural|natural selection', ['generación espontánea|generació espontània|spontaneous generation', 'fotosíntesis|fotosíntesi|photosynthesis'], 'Sobreviven los resistentes.|Sobreviuen els resistents.|The resistant survive.'),
      M('¿Quién llegó a la idea de la selección natural a la vez que Darwin?|Qui va arribar a la idea de la selecció natural alhora que Darwin?|Who reached the idea of natural selection at the same time as Darwin?', 'Alfred Russel Wallace|Alfred Russel Wallace|Alfred Russel Wallace', ['Gregor Mendel|Gregor Mendel|Gregor Mendel', 'Louis Pasteur|Louis Pasteur|Louis Pasteur'], 'Presentaron sus ideas juntos en 1858.|Van presentar les seues idees junts el 1858.|They presented their ideas together in 1858.'),
      TF('Los individuos cambian a propósito para adaptarse.|Els individus canvien a propòsit per a adaptar-se.|Individuals change on purpose to adapt.', false, 'La variación aparece al azar; el medio selecciona.|La variació apareix a l’atzar; el medi selecciona.|Variation is random; the environment selects.'),
    ]),
  '4E-BG-11': lesson(['Las adaptaciones son características que favorecen la supervivencia en un medio: morfológicas (forma, como las espinas del cactus), fisiológicas (funcionamiento, como orinar poco en el desierto) y de comportamiento (migrar, hibernar).|Les adaptacions són característiques que afavorixen la supervivència en un medi: morfològiques (forma, com les espines del cactus), fisiològiques (funcionament, com orinar poc en el desert) i de comportament (migrar, hivernar).|Adaptations are features that help survival in an environment: structural (shape, such as cactus spines), physiological (how the body works, such as producing little urine in deserts) and behavioural (migrating, hibernating).'],
    '¿Qué adaptaciones tiene un cactus?|Quines adaptacions té un cactus?|What adaptations does a cactus have?', ['Hojas convertidas en espinas: pierde menos agua.|Fulles convertides en espines: perd menys aigua.|Leaves turned into spines: less water loss.', 'Tallo grueso que almacena agua.|Tija grossa que emmagatzema aigua.|A thick stem that stores water.'], [
      M('El oso polar tiene grasa gruesa y pelo denso para…|L’ós polar té greix gruixut i pèl dens per a…|A polar bear has thick fat and dense fur to…', 'conservar el calor|conservar la calor|keep warm', ['nadar más rápido|nadar més ràpid|swim faster', 'cazar de día|caçar de dia|hunt by day'], 'Adaptación al frío.|Adaptació al fred.|Adaptation to cold.'),
      M('Las cigüeñas que viajan a África en invierno muestran una adaptación…|Les cigonyes que viatgen a Àfrica a l’hivern mostren una adaptació…|Storks flying to Africa for winter show an adaptation that is…', 'de comportamiento (migración)|de comportament (migració)|behavioural (migration)', ['morfológica|morfològica|structural', 'fisiológica|fisiològica|physiological'], 'Cambian de lugar según la estación.|Canvien de lloc segons l’estació.|They move with the seasons.'),
      M('El camaleón cambia de color para…|El camaleó canvia de color per a…|A chameleon changes colour to…', 'camuflarse y comunicarse|camuflar-se i comunicar-se|camouflage itself and communicate', ['hacer fotosíntesis|fer fotosíntesi|photosynthesise', 'respirar|respirar|breathe'], 'Adaptación de camuflaje.|Adaptació de camuflatge.|A camouflage adaptation.'),
      TF('Las plantas de hoja caduca pierden las hojas en otoño para ahorrar agua y energía en invierno.|Les plantes de fulla caduca perden les fulles a la tardor per a estalviar aigua i energia a l’hivern.|Deciduous trees drop leaves in autumn to save water and energy in winter.', true, 'Adaptación estacional.|Adaptació estacional.|A seasonal adaptation.'),
      M('Los peces tienen branquias, que son una adaptación para…|Els peixos tenen brànquies, que són una adaptació per a…|Fish have gills, an adaptation for…', 'respirar el oxígeno disuelto en el agua|respirar l’oxigen dissolt en l’aigua|breathing oxygen dissolved in water', ['volar|volar|flying', 'ver en la oscuridad|veure en la foscor|seeing in the dark'], 'Morfológica y fisiológica.|Morfològica i fisiològica.|Structural and physiological.'),
      M('Hibernar es…|Hivernar és…|Hibernating means…', 'reducir mucho la actividad en invierno|reduir molt l’activitat a l’hivern|greatly reducing activity in winter', ['cambiar de color|canviar de color|changing colour', 'comer más en invierno|menjar més a l’hivern|eating more in winter'], 'Como el lirón o algunos murciélagos.|Com el liró o algunes rates penades.|Like dormice or some bats.'),
    ]),
  '4E-BG-12': lesson(['Una población es el conjunto de individuos de una especie en un lugar; crece según natalidad, mortalidad y migraciones, hasta un límite (capacidad de carga). Una comunidad es el conjunto de poblaciones que conviven. Relaciones: intraespecíficas (familias, colonias, competencia) e interespecíficas (depredación, parasitismo, mutualismo, comensalismo).|Una població és el conjunt d’individus d’una espècie en un lloc; creix segons natalitat, mortalitat i migracions, fins a un límit (capacitat de càrrega). Una comunitat és el conjunt de poblacions que conviuen. Relacions: intraespecífiques (famílies, colònies, competència) i interespecífiques (depredació, parasitisme, mutualisme, comensalisme).|A population is all the individuals of one species in a place; it grows with births, deaths and migration up to a limit (carrying capacity). A community is all the populations living together. Relationships: within a species (families, colonies, competition) and between species (predation, parasitism, mutualism, commensalism).'],
    'Si aumentan los linces, ¿qué pasa con los conejos?|Si augmenten els linxs, què passa amb els conills?|If lynxes increase, what happens to rabbits?', ['Más depredadores comen más conejos.|Més depredadors mengen més conills.|More predators eat more rabbits.', 'Los conejos bajan; luego bajan los linces por falta de comida.|Els conills baixen; després baixen els linxs per falta de menjar.|Rabbits fall; then lynxes fall for lack of food.'], [
      M('Una colonia de abejas es una relación…|Una colònia d’abelles és una relació…|A bee colony is a relationship that is…', 'intraespecífica|intraespecífica|within a species', ['interespecífica|interespecífica|between species', 'parasitaria|parasitària|parasitic'], 'Misma especie.|Mateixa espècie.|Same species.'),
      M('El pez payaso y la anémona se benefician mutuamente:|El peix pallasso i l’anemone es beneficien mútuament:|The clownfish and anemone both benefit:', 'mutualismo|mutualisme|mutualism', ['parasitismo|parasitisme|parasitism', 'competencia|competència|competition'], 'Protección y limpieza.|Protecció i neteja.|Protection and cleaning.'),
      M('La capacidad de carga es…|La capacitat de càrrega és…|Carrying capacity is…', 'el máximo de individuos que el medio puede mantener|el màxim d’individus que el medi pot mantindre|the most individuals an environment can support', ['el peso de un animal|el pes d’un animal|an animal’s weight', 'el número de crías|el nombre de cries|the number of young'], 'Depende de los recursos.|Depén dels recursos.|It depends on resources.'),
      Nq('Una población de 500 tiene 80 nacimientos y 30 muertes en un año (sin migraciones). ¿Cuántos individuos hay al final?|Una població de 500 té 80 naixements i 30 morts en un any (sense migracions). Quants individus hi ha al final?|A population of 500 has 80 births and 30 deaths in a year (no migration). How many are there at the end?', 550, [610, 450, 580], '500 + 80 − 30.|500 + 80 − 30.|500 + 80 − 30.'),
      M('Una rémora que viaja pegada a un tiburón sin perjudicarlo:|Una rèmora que viatja apegada a un tauró sense perjudicar-lo:|A remora riding on a shark without harming it:', 'comensalismo|comensalisme|commensalism', ['mutualismo|mutualisme|mutualism', 'depredación|depredació|predation'], 'Uno se beneficia y el otro ni gana ni pierde.|Un se’n beneficia i l’altre ni guanya ni perd.|One benefits; the other is unaffected.'),
      TF('Las especies invasoras pueden desequilibrar una comunidad.|Les espècies invasores poden desequilibrar una comunitat.|Invasive species can unbalance a community.', true, 'Compiten o depredan a las autóctonas.|Competixen o depreden les autòctones.|They compete with or prey on natives.'),
    ]),
  '4E-BG-13': lesson(['Los ciclos biogeoquímicos mueven los elementos entre biosfera, atmósfera, hidrosfera y geosfera. Carbono: fotosíntesis, respiración, combustión, sedimentos. Nitrógeno: fijación por bacterias, nitrificación, desnitrificación. Fósforo: rocas → suelo → seres vivos → sedimentos. Las actividades humanas los alteran.|Els cicles biogeoquímics mouen els elements entre biosfera, atmosfera, hidrosfera i geosfera. Carboni: fotosíntesi, respiració, combustió, sediments. Nitrogen: fixació per bacteris, nitrificació, desnitrificació. Fòsfor: roques → sòl → éssers vius → sediments. Les activitats humanes els alteren.|Biogeochemical cycles move elements between biosphere, atmosphere, hydrosphere and geosphere. Carbon: photosynthesis, respiration, combustion, sediments. Nitrogen: fixation by bacteria, nitrification, denitrification. Phosphorus: rocks → soil → living things → sediments. Human activities disturb them.'],
    '¿Por qué el ciclo del fósforo no tiene fase atmosférica importante?|Per què el cicle del fòsfor no té fase atmosfèrica important?|Why does the phosphorus cycle have no major atmospheric stage?', ['El fósforo no forma gases habituales.|El fòsfor no forma gasos habituals.|Phosphorus forms no common gases.', 'Circula entre rocas, suelo, agua y seres vivos.|Circula entre roques, sòl, aigua i éssers vius.|It moves between rocks, soil, water and living things.'], [
      M('El 78 % del aire es nitrógeno, pero las plantas lo obtienen…|El 78 % de l’aire és nitrogen, però les plantes l’obtenen…|Air is 78% nitrogen, but plants get it…', 'del suelo, en forma de nitratos|del sòl, en forma de nitrats|from the soil, as nitrates', ['directamente del aire|directament de l’aire|straight from the air', 'de la luz|de la llum|from light'], 'Gracias a bacterias.|Gràcies a bacteris.|Thanks to bacteria.'),
      M('Los combustibles fósiles son carbono almacenado en…|Els combustibles fòssils són carboni emmagatzemat en…|Fossil fuels are carbon stored in…', 'la geosfera durante millones de años|la geosfera durant milions d’anys|the geosphere for millions of years', ['las nubes|els núvols|clouds', 'los volcanes activos|els volcans actius|active volcanoes'], 'Restos de seres vivos antiguos.|Restes d’éssers vius antics.|Remains of ancient organisms.'),
      TF('La deforestación altera el ciclo del carbono.|La desforestació altera el cicle del carboni.|Deforestation disrupts the carbon cycle.', true, 'Menos fotosíntesis y más CO₂ si se quema.|Menys fotosíntesi i més CO₂ si es crema.|Less photosynthesis, more CO₂ if burnt.'),
      M('La desnitrificación devuelve el nitrógeno…|La desnitrificació torna el nitrogen…|Denitrification returns nitrogen…', 'a la atmósfera como N₂|a l’atmosfera com a N₂|to the air as N₂', ['a las rocas|a les roques|to rocks', 'al núcleo terrestre|al nucli terrestre|to the Earth’s core'], 'La hacen bacterias.|La fan bacteris.|Bacteria do it.'),
      M('El exceso de fosfatos y nitratos en el agua causa…|L’excés de fosfats i nitrats en l’aigua causa…|Too much phosphate and nitrate in water causes…', 'eutrofización|eutrofització|eutrophication', ['lluvia ácida|pluja àcida|acid rain', 'agujero de ozono|forat d’ozó|ozone depletion'], 'Crecen algas y falta oxígeno.|Creixen algues i falta oxigen.|Algae bloom and oxygen runs out.'),
      M('El proceso que retira CO₂ de la atmósfera es…|El procés que retira CO₂ de l’atmosfera és…|The process that removes CO₂ from the air is…', 'la fotosíntesis|la fotosíntesi|photosynthesis', ['la respiración|la respiració|respiration', 'la combustión|la combustió|combustion'], 'Plantas, algas y cianobacterias.|Plantes, algues i cianobacteris.|Plants, algae and cyanobacteria.'),
    ]),
  '4E-BG-14': lesson(['La geosfera se estudia con ondas sísmicas, que cambian de velocidad al atravesar materiales distintos. Modelo geoquímico: corteza, manto y núcleo. Modelo dinámico: litosfera (rígida, dividida en placas), astenosfera (más plástica), mesosfera y núcleo externo (líquido) e interno (sólido).|La geosfera s’estudia amb ones sísmiques, que canvien de velocitat en travessar materials diferents. Model geoquímic: escorça, mantell i nucli. Model dinàmic: litosfera (rígida, dividida en plaques), astenosfera (més plàstica), mesosfera i nucli extern (líquid) i intern (sòlid).|The geosphere is studied using seismic waves, which change speed as they pass through different materials. Compositional model: crust, mantle and core. Dynamic model: lithosphere (rigid, broken into plates), asthenosphere (more plastic), mesosphere, outer core (liquid) and inner core (solid).'],
    '¿Cómo sabemos que el núcleo externo es líquido?|Com sabem que el nucli extern és líquid?|How do we know the outer core is liquid?', ['Las ondas S no atraviesan líquidos.|Les ones S no travessen líquids.|S-waves cannot pass through liquids.', 'No llegan al otro lado: hay una «zona de sombra».|No arriben a l’altre costat: hi ha una «zona d’ombra».|They do not reach the far side: there is a "shadow zone".'], [
      M('La litosfera está formada por…|La litosfera està formada per…|The lithosphere is made of…', 'la corteza y la parte superior del manto|l’escorça i la part superior del mantell|the crust and upper mantle', ['solo el núcleo|només el nucli|only the core', 'la atmósfera|l’atmosfera|the atmosphere'], 'Capa rígida dividida en placas.|Capa rígida dividida en plaques.|A rigid layer broken into plates.'),
      M('El núcleo interno es sólido porque…|El nucli intern és sòlid perquè…|The inner core is solid because…', 'la presión es enorme|la pressió és enorme|the pressure is enormous', ['está frío|està fred|it is cold', 'es de hielo|és de gel|it is made of ice'], 'Aunque está a más de 5 000 °C.|Encara que està a més de 5 000 °C.|Even though it is above 5,000 °C.'),
      TF('Las ondas P atraviesan sólidos y líquidos.|Les ones P travessen sòlids i líquids.|P-waves travel through solids and liquids.', true, 'Las S solo sólidos.|Les S només sòlids.|S-waves only through solids.'),
      M('La discontinuidad de Mohorovičić separa…|La discontinuïtat de Mohorovičić separa…|The Moho separates…', 'la corteza del manto|l’escorça del mantell|the crust from the mantle', ['el manto del núcleo|el mantell del nucli|the mantle from the core', 'la atmósfera de la hidrosfera|l’atmosfera de la hidrosfera|the atmosphere from the hydrosphere'], 'Las ondas aceleran al pasarla.|Les ones acceleren en passar-la.|Waves speed up as they cross it.'),
      M('El campo magnético terrestre se genera en…|El camp magnètic terrestre es genera en…|Earth’s magnetic field is generated in…', 'el núcleo externo líquido|el nucli extern líquid|the liquid outer core', ['la corteza|l’escorça|the crust', 'la atmósfera|l’atmosfera|the atmosphere'], 'Movimiento de hierro fundido.|Moviment de ferro fos.|Moving molten iron.'),
      M('La astenosfera es…|L’astenosfera és…|The asthenosphere is…', 'una capa del manto más plástica sobre la que se mueven las placas|una capa del mantell més plàstica sobre la qual es mouen les plaques|a more plastic mantle layer on which plates move', ['el fondo del mar|el fons de la mar|the sea floor', 'una capa de agua|una capa d’aigua|a layer of water'], 'Permite el movimiento de la litosfera.|Permet el moviment de la litosfera.|It lets the lithosphere move.'),
    ]),
  '4E-BG-15': lesson(['Tectónica de placas: la litosfera está dividida en placas que se mueven. Bordes divergentes (se separan: dorsales, se crea corteza), convergentes (chocan: subducción con fosas y volcanes, o cordilleras) y transformantes (se deslizan: fallas como San Andrés). Explica terremotos, volcanes y montañas.|Tectònica de plaques: la litosfera està dividida en plaques que es mouen. Vores divergents (se separen: dorsals, es crea escorça), convergents (xoquen: subducció amb fosses i volcans, o serralades) i transformants (llisquen: falles com Sant Andreu).|Plate tectonics: the lithosphere is broken into moving plates. Divergent boundaries (moving apart: ridges, new crust), convergent (colliding: subduction with trenches and volcanoes, or mountain ranges) and transform (sliding past: faults such as San Andreas). It explains earthquakes, volcanoes and mountains.'],
    '¿Por qué hay volcanes en los Andes?|Per què hi ha volcans en els Andes?|Why are there volcanoes in the Andes?', ['La placa oceánica de Nazca se hunde bajo Sudamérica.|La placa oceànica de Nazca s’enfonsa davall de Sud-amèrica.|The oceanic Nazca plate sinks under South America.', 'Subducción: se funde y sube magma.|Subducció: es fon i puja magma.|Subduction: it melts and magma rises.'], [
      M('En una dorsal oceánica, las placas…|En una dorsal oceànica, les plaques…|At a mid-ocean ridge, plates…', 'se separan|se separen|move apart', ['chocan|xoquen|collide', 'se deslizan lateralmente|llisquen lateralment|slide sideways'], 'Borde divergente.|Vora divergent.|Divergent boundary.'),
      M('La falla de San Andrés es un borde…|La falla de Sant Andreu és una vora…|The San Andreas Fault is a…', 'transformante|transformant|transform boundary', ['divergente|divergent|divergent boundary', 'de subducción|de subducció|subduction zone'], 'Las placas se rozan lateralmente.|Les plaques es freguen lateralment.|Plates grind past each other.'),
      TF('En la subducción, la placa más densa se hunde bajo la otra.|En la subducció, la placa més densa s’enfonsa davall de l’altra.|In subduction, the denser plate sinks beneath the other.', true, 'Normalmente la oceánica.|Normalment l’oceànica.|Usually the oceanic plate.'),
      M('Islandia es volcánica porque está sobre…|Islàndia és volcànica perquè està sobre…|Iceland is volcanic because it sits on…', 'una dorsal oceánica|una dorsal oceànica|a mid-ocean ridge', ['una fosa|una fossa|a trench', 'el centro de una placa sin actividad|el centre d’una placa sense activitat|the quiet centre of a plate'], 'Dorsal mesoatlántica.|Dorsal mesoatlàntica.|The Mid-Atlantic Ridge.'),
      M('Las fosas oceánicas más profundas están en zonas de…|Les fosses oceàniques més profundes estan en zones de…|The deepest ocean trenches are at…', 'subducción|subducció|subduction zones', ['dorsales|dorsals|ridges', 'puntos calientes|punts calents|hotspots'], 'Fosa de las Marianas.|Fossa de les Marianes.|The Mariana Trench.'),
      TF('El océano Atlántico se está ensanchando cada año.|L’oceà Atlàntic s’està eixamplant cada any.|The Atlantic Ocean is getting wider every year.', true, 'Unos centímetros al año.|Uns centímetres a l’any.|A few centimetres a year.'),
    ]),
  '4E-BG-16': lesson(['El relieve es el resultado de procesos internos (que lo levantan: pliegues, fallas, volcanes) y externos (que lo desgastan: erosión, transporte, sedimentación). Pliegue: deformación plástica (anticlinal, sinclinal). Falla: rotura con desplazamiento. El paisaje depende también de la roca y del clima.|El relleu és el resultat de processos interns (que l’alcen: plecs, falles, volcans) i externs (que el desgasten: erosió, transport, sedimentació). Plec: deformació plàstica (anticlinal, sinclinal). Falla: trencament amb desplaçament. El paisatge depén també de la roca i del clima.|Landscape results from internal processes (that raise it: folds, faults, volcanoes) and external ones (that wear it down: erosion, transport, deposition). Fold: plastic deformation (anticline, syncline). Fault: a break with movement. Landscape also depends on rock type and climate.'],
    '¿Qué diferencia hay entre pliegue y falla?|Quina diferència hi ha entre plec i falla?|What is the difference between a fold and a fault?', ['Pliegue: la roca se dobla sin romperse.|Plec: la roca es doblega sense trencar-se.|Fold: rock bends without breaking.', 'Falla: la roca se rompe y los bloques se desplazan.|Falla: la roca es trenca i els blocs es desplacen.|Fault: rock breaks and blocks move.'], [
      M('Un pliegue con forma de arco hacia arriba es…|Un plec amb forma d’arc cap amunt és…|An upward arch-shaped fold is…', 'un anticlinal|un anticlinal|an anticline', ['un sinclinal|un sinclinal|a syncline', 'una falla|una falla|a fault'], 'El sinclinal tiene forma de U.|El sinclinal té forma d’U.|A syncline is U-shaped.'),
      M('El relieve kárstico (cuevas, simas) se forma en rocas…|El relleu càrstic (coves, avencs) es forma en roques…|Karst landscapes (caves, sinkholes) form in…', 'calizas|calcàries|limestone', ['graníticas|granítiques|granite', 'volcánicas|volcàniques|volcanic rock'], 'El agua disuelve la caliza.|L’aigua dissol la calcària.|Water dissolves limestone.'),
      TF('Las montañas jóvenes suelen ser más altas y escarpadas que las antiguas.|Les muntanyes joves solen ser més altes i escarpades que les antigues.|Young mountains are usually higher and steeper than old ones.', true, 'Han tenido menos tiempo de erosión.|Han tingut menys temps d’erosió.|They have had less time to erode.'),
      M('Los procesos que crean relieve son sobre todo…|Els processos que creen relleu són sobretot…|Processes that build landscape are mainly…', 'internos (tectónica y volcanes)|interns (tectònica i volcans)|internal (tectonics and volcanoes)', ['externos (erosión)|externs (erosió)|external (erosion)', 'biológicos|biològics|biological'], 'Los externos lo desgastan.|Els externs el desgasten.|External processes wear it down.'),
      M('El clima influye en el relieve porque…|El clima influïx en el relleu perquè…|Climate affects landscape because…', 'determina qué agentes erosivos actúan|determina quins agents erosius actuen|it decides which erosion agents act', ['no influye|no influïx|it has no effect', 'crea volcanes|crea volcans|it creates volcanoes'], 'Hielo, agua o viento.|Gel, aigua o vent.|Ice, water or wind.'),
      M('Una falla normal se produce por fuerzas de…|Una falla normal es produïx per forces de…|A normal fault is caused by…', 'distensión (estiramiento)|distensió (estirament)|tension (stretching)', ['compresión|compressió|compression', 'gravedad lunar|gravetat lunar|the Moon’s gravity'], 'El bloque superior baja.|El bloc superior baixa.|The upper block drops.'),
    ]),
};
export default P;
